package imagesearch

import (
	"errors"

	"github.com/anthnel/devdesk/internal/oci"
)

// Verdict is one registry's answer to a search. The zero value is not a
// verdict: it means no answer yet, and Classify never returns it.
type Verdict int

const (
	// VerdictOK means rows were found.
	VerdictOK Verdict = iota + 1
	// VerdictNoResult means the registry answered and nothing matches.
	VerdictNoResult
	// VerdictRefused means unsupported or refused.
	VerdictRefused
	// VerdictFailed means network, deadline, 5xx, 429 or unreadable body.
	VerdictFailed
)

// String is the verdict as shown to the user.
func (v Verdict) String() string {
	switch v {
	case VerdictOK:
		return "ok"
	case VerdictNoResult:
		return "no result"
	case VerdictRefused:
		return "unsupported or refused"
	case VerdictFailed:
		return "failed"
	}
	return "pending"
}

// Outcome is a verdict and its marks. Invariant: Partial is set only with ok
// or no result (a partial walk that found nothing is still "no result"), never
// with refused or failed.
type Outcome struct {
	Verdict Verdict
	Partial bool
	Skipped bool
}

// ErrQueryTooShort: the catalog was not walked, the query is too short.
var ErrQueryTooShort = errors.New("query too short to walk a catalog")

// ErrPrefixNotInCatalog: no catalog name carries the entry's prefix.
var ErrPrefixNotInCatalog = errors.New("no catalog name carries the entry's prefix")

// Classify turns a search answer (error, row count, partial flag) into one
// Outcome. An error always wins over n and partial. With no error, n == 0
// keeps the Partial mark: the verdict is "no result" and Partial is set when
// the walk was cut short.
func Classify(err error, n int, partial bool) Outcome {
	switch {
	case err == nil && n == 0:
		return Outcome{Verdict: VerdictNoResult, Partial: partial}
	case err == nil:
		return Outcome{Verdict: VerdictOK, Partial: partial}
	case errors.Is(err, ErrQueryTooShort):
		return Outcome{Verdict: VerdictNoResult, Skipped: true}
	case errors.Is(err, ErrUnsupported), errors.Is(err, ErrPrefixNotInCatalog):
		return Outcome{Verdict: VerdictRefused}
	}
	var se *oci.StatusError
	if errors.As(err, &se) && refusedStatus(se) {
		return Outcome{Verdict: VerdictRefused}
	}
	return Outcome{Verdict: VerdictFailed}
}

// refusedStatus tells a refusal from a failure: the registry refusing the
// request (401, 403, 404, 405) or the token endpoint refusing the credentials
// (401, 403). Any other status, 429 and 5xx included, is a failure.
func refusedStatus(se *oci.StatusError) bool {
	switch se.Code {
	case 401, 403:
		return true
	case 404, 405:
		return se.Source != oci.SourceToken
	}
	return false
}
package imagesearch

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/url"
	"testing"

	"github.com/anthnel/devdesk/internal/oci"
)

type classifyCase struct {
	name    string
	err     error
	n       int
	partial bool
	want    Outcome
}

func classifyCases() []classifyCase {
	status := func(code int) error { return &oci.StatusError{Code: code} }
	token := func(code int) error { return &oci.StatusError{Code: code, Source: oci.SourceToken} }
	refused, failed := Outcome{Verdict: VerdictRefused}, Outcome{Verdict: VerdictFailed}
	return []classifyCase{
		{"rows", nil, 3, false, Outcome{Verdict: VerdictOK}},
		{"rows at the cap", nil, 100, true, Outcome{Verdict: VerdictOK, Partial: true}},
		{"empty answer", nil, 0, false, Outcome{Verdict: VerdictNoResult}},
		// DEVDESK-306 Q1=A: a walk cut at the cap with no match is not a
		// definitive "nothing": the verdict stays no result, with the mark.
		{"empty partial answer", nil, 0, true, Outcome{Verdict: VerdictNoResult, Partial: true}},
		{"query too short", ErrQueryTooShort, 0, false, Outcome{Verdict: VerdictNoResult, Skipped: true}},
		{"query too short wrapped", fmt.Errorf("x: %w", ErrQueryTooShort), 0, false, Outcome{Verdict: VerdictNoResult, Skipped: true}},
		{"unsupported", ErrUnsupported, 0, false, refused},
		{"prefix not in catalog", ErrPrefixNotInCatalog, 0, false, refused},
		// DEVDESK-629 (F1): a token realm refused for being off the origin is a failure
		// (rule 5), not a refusal by the registry.
		{"token realm off the origin", fmt.Errorf("search: %w (auth.example)", oci.ErrTokenRealmOffOrigin), 0, false, failed},
		{"registry 401", status(401), 0, false, refused},
		{"registry 403", status(403), 0, false, refused},
		{"registry 404", status(404), 0, false, refused},
		{"registry 405", status(405), 0, false, refused},
		{"token 401", token(401), 0, false, refused},
		{"token 403", token(403), 0, false, refused},
		{"token 404", token(404), 0, false, failed},
		{"token 500", token(500), 0, false, failed},
		{"429", status(429), 0, false, failed},
		{"500", status(500), 0, false, failed},
		{"502", status(502), 0, false, failed},
		{"503", status(503), 0, false, failed},
		{"400", status(400), 0, false, failed},
		{"301", status(301), 0, false, failed},
		{"wrapped 403", fmt.Errorf("hub search: %w", status(403)), 0, false, refused},
		{"deadline", context.DeadlineExceeded, 0, false, failed},
		{"deadline in url error", &url.Error{Op: "Get", URL: "https://x", Err: context.DeadlineExceeded}, 0, false, failed},
		{"canceled", context.Canceled, 0, false, failed},
		{"unreadable body", fmt.Errorf("decode: %w", &json.SyntaxError{}), 0, false, failed},
		{"network error", errors.New("connection refused"), 0, false, failed},
		{"error wins over n and partial", ErrUnsupported, 5, true, refused},
		{"failure wins over partial", errors.New("boom"), 5, true, failed},
	}
}

func TestClassify(t *testing.T) {
	for _, tc := range classifyCases() {
		t.Run(tc.name, func(t *testing.T) {
			if got := Classify(tc.err, tc.n, tc.partial); got != tc.want {
				t.Errorf("Classify(%v, %d, %v) = %+v, want %+v", tc.err, tc.n, tc.partial, got, tc.want)
			}
		})
	}
}

// One verdict per answer, and a mark only with its own verdict.
func TestClassifyMarksOnlyTheirVerdict(t *testing.T) {
	for _, tc := range classifyCases() {
		t.Run(tc.name, func(t *testing.T) {
			o := Classify(tc.err, tc.n, tc.partial)
			switch o.Verdict {
			case VerdictOK, VerdictNoResult, VerdictRefused, VerdictFailed:
			default:
				t.Fatalf("verdict = %d, want one of the four", o.Verdict)
			}
			if o.Partial && o.Verdict != VerdictOK && o.Verdict != VerdictNoResult {
				t.Errorf("Partial set with %v", o.Verdict)
			}
			if o.Partial && o.Skipped {
				t.Error("Partial and Skipped set together")
			}
			if o.Skipped && o.Verdict != VerdictNoResult {
				t.Errorf("Skipped set with %v", o.Verdict)
			}
		})
	}
}

func TestVerdictString(t *testing.T) {
	for v, want := range map[Verdict]string{
		VerdictOK:       "ok",
		VerdictNoResult: "no result",
		VerdictRefused:  "unsupported or refused",
		VerdictFailed:   "failed",
		Verdict(0):      "pending",
	} {
		if got := v.String(); got != want {
			t.Errorf("Verdict(%d).String() = %q, want %q", int(v), got, want)
		}
	}
}

func TestSentinelsAreDistinctErrorsWithAMessage(t *testing.T) {
	if ErrQueryTooShort.Error() == "" || ErrPrefixNotInCatalog.Error() == "" {
		t.Fatal("sentinels need a message")
	}
	if errors.Is(ErrQueryTooShort, ErrPrefixNotInCatalog) || errors.Is(ErrQueryTooShort, ErrUnsupported) {
		t.Error("sentinels must be distinct")
	}
}

// wantRecorded pins what a fixture recorded, so that a regenerated one with another
// answer fails here before the replay can hide it.
func wantRecorded(t *testing.T, f nexusfixture.Fixture, target string, status int) {
	t.Helper()
	if len(f.Exchanges) != 1 || f.Exchanges[0].Target != target || f.Exchanges[0].Status != status {
		t.Fatalf("%s no longer records %s -> %d: the measurement changed", f.Name, target, status)
	}
}

func TestCachedOnlyLineOnMeasuredCutUpstream(t *testing.T) {
	const (
		// The hosted catalog is one request answered the same way in both states. Only
		// the cut state is a fixture of this campaign (the control that the cut leaves
		// the hosted repository alone); the nominal one comes from NX-03 (catalog).
		hostedCut     = "cut2-catalog-hosted-path--admin"
		hostedNominal = "catalog-hosted-path-n1000--admin"
		hostedMember  = "nx/docker-hosted"
		proxyMember   = "nx/docker-proxy"
	)
	// Two members reached by path, as discovery stores them for a Nexus group on the
	// HTTP port: the hosted one (answers, no mirror name) and the proxy.
	members := []struct {
		name    string
		proxy   string // fixture of the proxy catalog
		hosted  string // fixture of the hosted catalog (campaign catalog if nominal, else cachedonly)
		status  int
		verdict imagesearch.Verdict
		want    searchSummary // the names of the level 1 header, by class, unabbreviated
		rows    []string      // Repo of each row, sorted
		level   string        // journal level of the verdict ("" = no journal line)
		cause   string
	}{
		{
			name: "upstream reachable", proxy: "nominal-catalog-proxy-path--admin", hosted: hostedNominal, status: 200,
			verdict: imagesearch.VerdictOK,
			want:    searchSummary{CachedOnly: []string{hostedMember + cachedNoResultMark, proxyMember}},
			rows:    []string{"docker-proxy/mirror/cached", "docker-proxy/mirror/uncached"}, // under the proxy member
		},
		{
			// First read after the cut: 502 from Nexus. Failed, and NOT Cached only: the
			// proxy is not in the Cached only line although it is a proxy of a Nexus group.
			name: "first read after the cut", proxy: "cut1-catalog-proxy-path--admin", hosted: hostedCut, status: 502,
			verdict: imagesearch.VerdictFailed,
			want:    searchSummary{Failed: []string{proxyMember}, CachedOnly: []string{hostedMember + cachedNoResultMark}},
			level:   "ERROR", cause: "502",
		},
		{
			// Once Nexus has blocked the proxy: 404 "Remote Auto Blocked". Refused (a 404 is
			// a refusal), listed as "unsupported", not Cached only and not Failed.
			name: "proxy auto-blocked", proxy: "cut2-catalog-proxy-path--admin", hosted: hostedCut, status: 404,
			verdict: imagesearch.VerdictRefused,
			want:    searchSummary{Refused: []string{proxyMember}, CachedOnly: []string{hostedMember + cachedNoResultMark}},
			level:   "INFO", cause: "404",
		},
	}
	for _, tc := range members {
		t.Run(tc.name, func(t *testing.T) {
			hostedCampaign := "cachedonly"
			if tc.hosted == hostedNominal {
				hostedCampaign = "catalog"
			}
